var saved = flow.get('config', 'persistent');
var defaults = {
    socOnThreshold: 70,
    tempOnThreshold: 20,
    voltageOnThreshold: 53.5,
    socOffThreshold: 65,
    timeOnHour: 9,
    timeOffHour: 19,
    onDelay: 60,
    offDelay: 60,
    targetTemp: 24,
    mode: 'cool',
    fanSpeed: 'auto'
};
var config = Object.assign({}, defaults, saved || {});
flow.set('config', config);
flow.set('config', config, 'persistent');
if (!flow.get('acState')) {
    flow.set('acState', {power:false,lastChange:Date.now(),conditionsMetSince:null,conditionsNotMetSince:null,manualMode:false});
}
flow.set('currentValues', {soc:0,batteryVoltage:0,batteryState:'Unknown',batterySystemState:'Unknown',batterySystemStateNum:-1,temperature:0,tempReceived:false,outsideTemp:0,outsideTempReceived:false});
node.status({fill:'green',shape:'dot',text:'Config loaded'});
msg.payload = config;
return msg;

var values = flow.get('currentValues') || {soc:0,batteryVoltage:0,batteryState:'Unknown',batterySystemState:'Unknown',batterySystemStateNum:-1,temperature:0,tempReceived:false,outsideTemp:0,outsideTempReceived:false};

var path = msg.path || msg.topic || '';

if (path.indexOf('Battery SOC') !== -1) {
    values.soc = (msg.payload !== null && msg.payload !== undefined) ? Number(msg.payload) : 0;
}
else if (path.indexOf('Battery State') !== -1) {
    var sysState = Number(msg.payload);
    var sysNames = {0:'Idle',1:'Charging',2:'Discharging'};
    values.batterySystemState    = sysNames[sysState] || ('State:' + sysState);
    values.batterySystemStateNum = sysState;
}
else if (path.indexOf('Battery Voltage') !== -1) {
    values.batteryVoltage = (msg.payload !== null && msg.payload !== undefined) ? Number(msg.payload) : 0;
    var v = values.batteryVoltage;
    if      (v >= 56.0) { values.batteryState = 'Absorption'; }
    else if (v >= 53.5) { values.batteryState = 'Float';      }
    else if (v >  0)    { values.batteryState = 'Bulk';       }
    else                { values.batteryState = 'Unknown';    }
}
else if (path.indexOf('Ruuvi Inside') !== -1) {
    if (msg.payload !== null && msg.payload !== undefined) {
        values.temperature  = Number(msg.payload);
        values.tempReceived = true;
    }
}
else if (path.indexOf('Ruuvi Outside') !== -1) {
    if (msg.payload !== null && msg.payload !== undefined) {
        values.outsideTemp         = Number(msg.payload);
        values.outsideTempReceived = true;
    }
}

flow.set('currentValues', values);

var inStr   = values.tempReceived        ? values.temperature.toFixed(1) + 'C' : '---';
var outStr  = values.outsideTempReceived ? values.outsideTemp.toFixed(1) + 'C' : '---';
var voltStr = values.batteryVoltage > 0  ? values.batteryVoltage.toFixed(2) + 'V' : '?V';
node.status({text:'SOC:' + Math.round(values.soc||0) + '% ' + voltStr + ' ' + (values.batteryState||'?') + ' In:' + inStr + ' Out:' + outStr});

return {payload: values};

var values = msg.payload || {};
var state  = flow.get('acState')  || {};
var config = flow.get('config')   || {};

var soc     = (values.soc !== undefined)            ? values.soc            : 0;
var temp    = (values.temperature !== undefined)    ? values.temperature    : 0;
var voltage = (values.batteryVoltage !== undefined) ? values.batteryVoltage : 0;
var battSt  = values.batteryState || '?';
var outside = values.outsideTempReceived ? values.outsideTemp : null;

var socMsg  = {payload: Math.round(soc)};
var tempMsg = {payload: parseFloat(temp.toFixed(1))};

var battDisplay = voltage > 0 ? battSt + ' (' + voltage.toFixed(2) + 'V)' : battSt;
var battStateMsg   = {payload: battDisplay};
var acStatusMsg    = {payload: state.power ? 'ON' : 'OFF'};
var modeTextMsg    = {payload: state.manualMode ? 'MANUAL' : 'AUTOMATIC'};

var outsideDisplay;
if (outside !== null) {
    var hint = '';
    if (outside < 20)      hint = ' → Ventilate';
    else if (outside > 30) hint = ' → Cool early';
    outsideDisplay = outside.toFixed(1) + '°C' + hint;
} else {
    outsideDisplay = 'no sensor';
}
var outsideTempMsg = {payload: outsideDisplay};

var tempOnThr = config.tempOnThreshold || 22;
var effectiveTempOn = tempOnThr;
if (outside !== null) {
    if (outside < 20)      effectiveTempOn = tempOnThr + 3;
    else if (outside > 30) effectiveTempOn = Math.max(tempOnThr - 2, 18);
}

var statusText = '';
var onHour    = config.timeOnHour  !== undefined ? config.timeOnHour  : 6;
var offHour   = config.timeOffHour !== undefined ? config.timeOffHour : 21;
var socOnThr  = config.socOnThreshold    || 70;
var voltOnThr = config.voltageOnThreshold || 53.5;

if (state.manualMode) {
    statusText = state.power ? 'Manually on' : 'Manually off';
} else if (state.power) {
    statusText = 'Running | SOC ' + Math.round(soc) + '% | ' + battDisplay;
} else {
    var simClock = global.get('simClock');
    var hour = (simClock && simClock.enabled) ? Number(simClock.hour) : new Date().getHours();
    if (hour < onHour || hour >= offHour) {
        statusText = 'Quiet hours (' + onHour + ':00–' + offHour + ':00)';
    } else if (soc < socOnThr) {
        statusText = 'Waiting: SOC ' + Math.round(soc) + '% < ' + socOnThr + '%';
    } else if (!values.tempReceived) {
        statusText = 'Waiting: No inside sensor!';
    } else if (temp < effectiveTempOn) {
        var effStr = (effectiveTempOn !== tempOnThr) ? ' (eff. ' + effectiveTempOn + 'C, Outside: ' + (outside !== null ? outside.toFixed(1) : '?') + 'C)' : '';
        statusText = 'Waiting: Inside ' + temp.toFixed(1) + 'C < ' + effectiveTempOn + 'C' + effStr;
    } else if (voltage < voltOnThr) {
        statusText = 'Waiting: ' + voltage.toFixed(2) + 'V < ' + voltOnThr + 'V (Bulk)';
    } else if (values.batterySystemStateNum === 2) {
        statusText = 'Waiting: No PV – battery discharging';
    } else {
        statusText = 'Conditions met – starting soon...';
    }
}
var statusMsg = {payload: statusText};

return [socMsg, tempMsg, battStateMsg, acStatusMsg, modeTextMsg, statusMsg, outsideTempMsg];

var config = flow.get('config') || {};
var values = flow.get('currentValues') || {};
var state  = flow.get('acState') || {};

var now  = Date.now();
// Sim clock override (test tooling): when enabled, the time-of-day gate
// uses a fixed hour instead of the real clock. Read from GLOBAL context
// (the override is set from the mocks tab, a different flow). Date.now()
// (delays/watchdog) stays real.
var simClock = global.get('simClock');
var hour = (simClock && simClock.enabled) ? Number(simClock.hour) : new Date().getHours();

var soc     = values.soc || 0;
var temp    = (values.temperature !== undefined) ? values.temperature : 0;
var voltage = values.batteryVoltage || 0;
var outside = values.outsideTempReceived ? values.outsideTemp : null;

var onHour    = config.timeOnHour   !== undefined ? config.timeOnHour   : 6;
var offHour   = config.timeOffHour  !== undefined ? config.timeOffHour  : 21;
var socOffThr = config.socOffThreshold    || 65;
var socOnThr  = config.socOnThreshold     || 70;
var tempOnThr = config.tempOnThreshold    || 22;
var voltOnThr = config.voltageOnThreshold || 53.5;
var onDelay   = config.onDelay  || 120;
var offDelay  = config.offDelay || 60;

// Dynamic switch-on temperature based on the outside temperature
var effectiveTempOn = tempOnThr;
if (outside !== null) {
    if (outside < 20) {
        effectiveTempOn = tempOnThr + 3;  // Outside cool: ventilation is enough
    } else if (outside > 30) {
        effectiveTempOn = Math.max(tempOnThr - 2, 18);  // Outside hot: cool earlier
    }
}

if (state.manualMode) {
    node.status({fill:'blue',shape:'dot',text:'Manual: ' + (state.power ? 'ON' : 'OFF')});
    return null;
}

var timeOK = (hour >= onHour && hour < offHour);
if (!timeOK) {
    if (state.power) {
        state.power = false;
        state.conditionsNotMetSince = null;
        flow.set('acState', state);
        node.status({fill:'grey',shape:'dot',text:'Quiet hours'});
        return {payload: {action:'off',reason:'Outside operating hours'}};
    }
    node.status({fill:'grey',shape:'ring',text:'Quiet hours (' + onHour + ':00–' + offHour + ':00)'});
    return null;
}

if (soc < socOffThr) {
    if (state.power) {
        if (!state.conditionsNotMetSince) {
            state.conditionsNotMetSince = now;
            flow.set('acState', state);
        }
        var waited = (now - state.conditionsNotMetSince) / 1000;
        if (waited >= offDelay) {
            state.power = false;
            state.conditionsNotMetSince = null;
            flow.set('acState', state);
            var r = 'SOC ' + Math.round(soc) + '% < ' + socOffThr + '%';
            node.status({fill:'red',shape:'dot',text:'OFF: ' + r});
            return {payload: {action:'off',reason:r}};
        }
        node.status({fill:'yellow',shape:'dot',text:'OFF in ' + Math.round(offDelay-waited) + 's'});
        return null;
    }
}

// stateOK: 0=Idle (battery full) or 1=Charging = PV available
// voltOK as a night guard: at night the voltage drops below 53.5V even at State 0
var socOK   = soc >= socOnThr;
var tempOK  = temp >= effectiveTempOn;
var voltOK  = voltage >= voltOnThr;
var stateOK = (values.batterySystemStateNum === 1 || values.batterySystemStateNum === 0);
var battOK  = voltOK && stateOK;
var allOK   = socOK && tempOK && battOK;

if (!state.power && allOK) {
    if (!state.conditionsMetSince) {
        state.conditionsMetSince = now;
        flow.set('acState', state);
    }
    var waited2 = (now - state.conditionsMetSince) / 1000;
    if (waited2 >= onDelay) {
        state.power = true;
        state.conditionsMetSince = null;
        state.conditionsNotMetSince = null;
        flow.set('acState', state);
        var r2 = 'SOC ' + Math.round(soc) + '% | ' + voltage.toFixed(2) + 'V | In:' + temp.toFixed(1) + 'C';
        node.status({fill:'green',shape:'dot',text:'ON: ' + r2});
        return {payload: {action:'on',reason:r2}};
    }
    node.status({fill:'yellow',shape:'dot',text:'ON in ' + Math.round(onDelay-waited2) + 's'});
    return null;
}

if (!allOK) {
    state.conditionsMetSince = null;
    flow.set('acState', state);
}

if (state.power) {
    state.conditionsNotMetSince = null;
    flow.set('acState', state);
    node.status({fill:'green',shape:'dot',text:'Running | ' + voltage.toFixed(2) + 'V | SOC ' + Math.round(soc) + '%'});
} else {
    var w = [];
    if (!socOK)   w.push('SOC<' + socOnThr + '%');
    if (!tempOK)  w.push('In:' + temp.toFixed(1) + '<' + effectiveTempOn + 'C');
    if (!voltOK)  w.push(voltage.toFixed(2) + 'V<' + voltOnThr + 'V');
    if (!stateOK) w.push('Discharging');
    node.status({fill:'grey',shape:'ring',text:'Waiting: ' + w.join(' | ')});
}

return null;

var config = flow.get('config') || {};
var action = msg.payload.action;
var greeMsg = {topic: action};
if (action === 'on') {
    greeMsg.payload = {power:'on',mode:config.mode||'cool',temperature:config.targetTemp||24,fanSpeed:config.fanSpeed||'auto'};
    node.status({fill:'green',shape:'dot',text:'ON: ' + (config.targetTemp||24) + 'C'});
} else if (action === 'off') {
    greeMsg.payload = {power: 'off'};
    node.status({fill:'red',shape:'dot',text:'OFF sent'});
}
return greeMsg;

var state = flow.get('acState') || {};
state.manualMode = msg.payload;
flow.set('acState', state);
if (!state.manualMode) {
    node.status({fill:'green',shape:'ring',text:'Automatic active'});
} else {
    node.status({fill:'blue',shape:'dot',text:'Manual active'});
}
var values = flow.get('currentValues') || {};
return {payload: values};

var config = flow.get('config') || {};
var state  = flow.get('acState') || {};
var cmd    = msg.payload;
if (!state.manualMode) {
    node.status({fill:'yellow',shape:'ring',text:'Enable Manual mode first!'});
    return null;
}
var greeMsg = {topic: cmd};
if (cmd === 'on') {
    state.power = true;
    flow.set('acState', state);
    greeMsg.payload = {power:'on',mode:config.mode||'cool',temperature:config.targetTemp||24,fanSpeed:config.fanSpeed||'auto'};
    node.status({fill:'green',shape:'dot',text:'Manual ON'});
} else if (cmd === 'off') {
    state.power = false;
    flow.set('acState', state);
    greeMsg.payload = {power: 'off'};
    node.status({fill:'red',shape:'dot',text:'Manual OFF'});
}
var values = flow.get('currentValues') || {};
return [greeMsg, {payload: values}];

var c = flow.get('config') || {};
node.send([
    [{payload: c.targetTemp      || 24}],
    [{payload: c.tempOnThreshold || 22}],
    [{payload: c.timeOnHour      || 6}],
    [{payload: c.timeOffHour     || 21}],
    [{payload: c.socOnThreshold  || 70}],
    [{payload: c.socOffThreshold || 65}]
]);
return null;

var config = flow.get('config') || {};
var key   = msg.topic;
var value = Number(msg.payload);
if (key === 'socOffThreshold' && value >= (config.socOnThreshold || 70)) {
    node.status({fill:'red',shape:'dot',text:'Error: OFF-SOC (' + value + '%) must be < ON-SOC (' + (config.socOnThreshold||70) + '%)'});
    return null;
}
if (key === 'socOnThreshold' && value <= (config.socOffThreshold || 65)) {
    node.status({fill:'red',shape:'dot',text:'Error: ON-SOC (' + value + '%) must be > OFF-SOC (' + (config.socOffThreshold||65) + '%)'});
    return null;
}
if (key === 'timeOnHour' && value >= (config.timeOffHour || 21)) {
    node.status({fill:'red',shape:'dot',text:'Error: From (' + value + 'h) must be < Until (' + (config.timeOffHour||21) + 'h)'});
    return null;
}
if (key === 'timeOffHour' && value <= (config.timeOnHour || 6)) {
    node.status({fill:'red',shape:'dot',text:'Error: Until (' + value + 'h) must be > From (' + (config.timeOnHour||6) + 'h)'});
    return null;
}
config[key] = value;
flow.set('config', config);
flow.set('config', config, 'persistent');
node.status({fill:'green',shape:'dot',text: key + ' = ' + value + ' ✓'});
return null;

// Detects Gree reconnection and triggers a resync
var now = Date.now();
var lastOutput = flow.get('lastGreeOutput') || 0;
var wasAlive   = flow.get('greeWasAlive') || false;

// Detect reconnect:
//   - lastOutput=0  → very first output at all
//   - lastOutput >5min old → was offline and is back now
//   - wasAlive=false → was marked as not alive
var ageMin = lastOutput > 0 ? (now - lastOutput)/1000/60 : 999;
var reconnect = (!wasAlive) || (ageMin > 5);

flow.set('lastGreeOutput', now);
flow.set('greeWasAlive', true);
flow.set('greeErrorCount', 0);

if (reconnect) {
    node.status({fill:'blue', shape:'dot',
        text: 'Reconnect detected -> triggering resync'});
    return {payload: 'resync'};
}

node.status({fill:'green', shape:'dot', text: new Date().toLocaleTimeString()});
return null;

var last = flow.get('lastGreeOutput') || 0;
var now  = Date.now();

// First run after start: initialize the timer with now
// so the 20-min deadline also runs even if a connection never came
if (last === 0) {
    flow.set('lastGreeOutput', now);
    node.status({fill:'yellow', shape:'ring', text: 'Watchdog started, waiting for contact'});
    return null;
}

var age = (now - last) / 1000 / 60;  // minutes

if (age > 20) {
    node.status({fill:'red', shape:'dot',
        text: 'No output for ' + Math.round(age) + 'min -> restart'});
    flow.set('lastGreeOutput', 0);  // reset for the next cycle
    return {payload: 'watchdog-restart'};
}

node.status({fill:'green', shape:'dot',
    text: 'OK, last output ' + Math.round(age) + 'min ago'});
return null;

// Resync after reconnect: sends the current desired state to the AC
var config = flow.get('config') || {};
var state  = flow.get('acState') || {};

if (state.power) {
    // Desired state: ON - resend the full configuration
    var greeMsg = {
        topic: 'on',
        payload: {
            power:       'on',
            mode:        config.mode || 'cool',
            temperature: config.targetTemp || 24,
            fanSpeed:    config.fanSpeed || 'auto'
        }
    };
    node.status({fill:'green', shape:'dot',
        text: 'Resync ON @ ' + (config.targetTemp||24) + 'C'});
    return greeMsg;
} else {
    // Desired state: OFF - send explicit OFF to be safe
    node.status({fill:'red', shape:'dot', text: 'Resync OFF'});
    return {topic: 'off', payload: {power: 'off'}};
}
